function score(q,qt){var best=0,bi=null;IDX.forEach(function(x){var s=0;x.p.forEach(function(p,i){if(!p)return;if(q===p)s=Math.max(s,10+(x.e.t==='prat'?.5:0));else if(p.length>3&&q.indexOf(p)>=0)s=Math.max(s,6+Math.min(p.length,12)/6);var T=x.t[i];if(!T.length)return;var hit=0;T.forEach(function(t){if(qt.some(function(u){return u===t||(t.length>4&&u[0]===t[0]&&lev(u,t)<=1)||(t.length>8&&u[0]===t[0]&&lev(u,t)<=2)}))hit++});var f=hit/T.length;if(hit&&f>=.6)s=Math.max(s,f*5+hit*.4)});if(s>best){best=s;bi=x.e}});return {s:best,e:bi}}
var SUT=/\b([1-8])\.([1-4])\.(\d{1,3})\b/;
function sutra(n){if(!X.ashta.length)return 'The sūtra data is still loading. Please ask again in a moment.';var r=X.ashta.filter(function(x){return x[0]===n})[0];if(!r)return null;var b=window.NEXUS_CONTENT&&NEXUS_CONTENT.bridges[n];return 'Aṣṭādhyāyī '+n+': '+r[1]+' ('+r[2]+'). Type '+r[5]+'. Words carried forward: '+(r[4].length?r[4].join(' · '):'none listed')+'. Word split: '+r[3]+'. '+(b?'Bridge idea (an interpretation): '+b:'English meaning: UNKNOWN in source.')+' Cite: Aṣṭādhyāyī · '+n+' · ashtadhyayi-com/data.'}
